import{r as m,ap as j,aq as y,f as S,W as R,V as E,ar as O,U as w,as as I,ao as M,j as e,Z as P,S as u,I as q,B as p,x as g,a0 as F}from"./index-DGd4-8aL.js";import{C as v,b as f,c as h,d as N,a as C}from"./card-94qZ9VgF.js";import{B as z}from"./badge-DbhujtuD.js";import{M as B}from"./map-D4z8W8xp.js";import{C as D}from"./chart-no-axes-column-CAoo2S4A.js";import{A as U}from"./activity-OHbr8Omo.js";import{B as T}from"./book-open-DPPXGKkg.js";import{A as G}from"./arrow-right-Bm_ZrdXS.js";import{C as L}from"./chevron-right-Dh4_JL7-.js";const b=[{id:"dashboard",icon:j,title:"Dashboard",badge:"Visao Geral",badgeColor:"bg-blue-500/10 text-blue-600 border-blue-200",summary:"Painel principal com indicadores-chave de desempenho (KPIs) do negocio, graficos de evolucao e atividade recente.",subsections:[{title:"O que voce encontra aqui",content:"Ao abrir o sistema, o Dashboard mostra um resumo executivo: total de leads ativas, deals em andamento, ativos cadastrados e valor total do portfolio. Os cards superiores mostram numeros em tempo real — tudo o que esta acontecendo no seu funil de negocios."},{title:"Graficos e tendencias",content:"O grafico de area mostra a evolucao semanal de leads e deals, permitindo visualizar se a operacao esta crescendo. Abaixo, a lista de deals recentes mostra os negocios com maior movimentacao, com nome da empresa, valor e estagio atual."},{title:"Como usar",content:"Use o Dashboard como ponto de partida diario. Verifique se ha leads novas para qualificar, deals parados que precisam de atencao, e se o pipeline esta saudavel. Nao e necessario nenhuma acao — os dados sao atualizados automaticamente."}]},{id:"prospeccao",icon:y,title:"Prospeccao",badge:"Busca B2B",badgeColor:"bg-indigo-500/10 text-indigo-600 border-indigo-200",summary:"Motor de busca avancado para encontrar empresas por CNPJ, CNAE, porte, localizacao e situacao cadastral. Usa dados publicos da Receita Federal.",subsections:[{title:"Como buscar empresas",content:"Ha duas formas: (1) Busca por CNPJ — digite o CNPJ completo e o sistema busca os dados na Receita Federal via API CNPJA, trazendo razao social, endereco, socios, atividades e contato. (2) Busca avancada — use os filtros de CNAE (arvore hierarquica), UF, municipio, porte, situacao cadastral e natureza juridica para encontrar empresas por segmento."},{title:"Filtros avancados",content:"O seletor de CNAE usa uma arvore hierarquica: Secao > Divisao > Grupo > Classe. Exemplo: para buscar mineradoras, selecione 'B - Industrias Extrativas' > '07 - Extracao de minerais metalicos'. Combine com UF e porte para refinar. O filtro de situacao permite ver apenas empresas ativas."},{title:"Importar para o sistema",content:"Ao encontrar uma empresa interessante, clique em 'Importar'. A empresa e salva no banco de dados para acompanhamento. Se a empresa ja existir, o sistema avisa."}],flow:"Filtros → Buscar → Resultado → Importar → Empresas"},{id:"empresas",icon:S,title:"Empresas",badge:"Base de Dados",badgeColor:"bg-slate-500/10 text-slate-600 border-slate-200",summary:"Base centralizada de todas as empresas importadas. Permite visualizar, filtrar e acessar detalhes completos de cada empresa.",subsections:[{title:"Visoes disponiveis",content:"O menu Empresas tem tres sub-paginas: 'Todas as Empresas' (base completa), 'Leads Ativas' (empresas marcadas como lead em qualificacao) e 'Desqualificadas' (leads que foram descartadas). Use os filtros laterais de porte, estado e cidade para encontrar rapidamente."},{title:"Detalhe da empresa",content:"Ao clicar em uma empresa, voce acessa o detalhe com varias abas: Resumo (dados cadastrais, socios, endereco), Contato (telefones, emails, com indicacao de fonte — Receita Federal, Enrichment Web ou Verificado), Pesquisa (notas de pesquisa e dados verificados), Deals (historico de negocios), Timeline (eventos registrados)."},{title:"Dados Verificados na empresa",content:"Na aba de detalhe, a secao 'Dados Verificados' (com borda verde) permite salvar: telefone principal, email, WhatsApp, nome do contato, cargo e observacoes. Esses dados ficam salvos e sao usados em todo o sistema — nos cadastros e nas consultas."},{title:"Enrichment Web",content:"O botao 'Enriquecer' busca informacoes adicionais na web (telefones, emails, redes sociais) usando um scraper automatico. Os dados encontrados sao marcados como 'Enrichment Web' para diferencia-los dos dados da Receita Federal."}]},{id:"ativos",icon:R,title:"Ativos",badge:"Portfolio",badgeColor:"bg-emerald-500/10 text-emerald-600 border-emerald-200",summary:"Inventario completo de ativos em oferta: fazendas, minas, negocios M&A, FIIs, agronegocio e energia renovavel.",subsections:[{title:"Tipos de ativo",content:"As categorias incluem Terras & Fazendas (TERRA), Mineracao (MINA), Negocios M&A (NEGOCIO), Desenvolvimento Imobiliario (DESENVOLVIMENTO), Agronegocio (AGRO) e Energia Renovavel (ENERGIA). Fundos não fazem parte do Mavrion."},{title:"Filtros por tipo",content:"No sidebar, o submenu Ativos permite filtrar por tipo diretamente: clicar em 'Terras & Fazendas' mostra apenas ativos do tipo TERRA, clicar em 'Mineracao' mostra MINA, etc. 'Todos os Ativos' mostra o inventario completo."},{title:"Cadastrar ativo",content:"Para cadastrar, clique em 'Novo Ativo'. Preencha: titulo, tipo, localizacao (estado/cidade), preco pedido, area em hectares, matricula do imovel e observacoes. Ativos podem ser vinculados a processos ANM ou propriedades CAR."},{title:"Detalhe do ativo",content:"Ao clicar em um ativo, voce ve o detalhe completo com todas as informacoes, mapa de localizacao (quando disponivel), historico de modificacoes e deals associados."}]},{id:"anm",icon:B,title:"Portal ANM",badge:"Geoespacial",badgeColor:"bg-cyan-500/10 text-cyan-600 border-cyan-200",summary:"Integracao com a Agencia Nacional de Mineracao (ANM). Busca processos minerarios, visualiza poligonos no mapa e identifica oportunidades.",subsections:[{title:"O que e o Portal ANM",content:"A ANM (Agencia Nacional de Mineracao) e o orgao do governo que gerencia todos os processos minerarios do Brasil. Nosso modulo consulta diretamente os dados publicos da ANM e plota os poligonos das areas minerarias no mapa, similar ao SIGMINE."},{title:"Filtros de busca",content:"Use os filtros no painel lateral para refinar: UF (estado), Substancia (ouro, ferro, calcario, areia, etc.), Fase do processo (Requerimento, Autorizacao, Concessao, Disponibilidade, etc.) e ano. A fase 'Disponibilidade' e especialmente interessante pois indica areas que podem ser requeridas."},{title:"Mapa interativo",content:"Os resultados aparecem como poligonos coloridos no mapa Leaflet. Ao clicar em um poligono, um popup mostra os detalhes: Titular, Fase (badge azul), Substancia, Uso, Area, UF, Ano e Ultimo Evento (badge amarelo). Isso permite avaliar rapidamente se a area tem potencial."},{title:"Da ANM ao cadastro de ativos",content:"Ao identificar um processo interessante (ex: uma area de calcario em 'Disponibilidade' no MT), voce pode importar como ativo para pesquisar o titular e os dados da area."}],flow:"Filtrar (UF + Substância + Fase) → Ver no Mapa → Clicar Polígono → Analisar Detalhes → Importar como Ativo"},{id:"geo-rural",icon:E,title:"Prospeccao Rural (Geo-Rural)",badge:"Geoespacial",badgeColor:"bg-cyan-500/10 text-cyan-600 border-cyan-200",summary:"Analise geoespacial de propriedades rurais via SICAR (CAR), com camadas de rios, energia, altitude e score de oportunidade.",subsections:[{title:"O que e o Geo-Rural",content:"O modulo Geo-Rural consulta o SICAR (Sistema Nacional de Cadastro Ambiental Rural) e plota propriedades rurais no mapa. Ele calcula um 'Score de Oportunidade' baseado em proximidade de rios, linhas de energia, altitude e tamanho da propriedade."},{title:"Camadas do mapa",content:"O mapa pode exibir multiplas camadas: propriedades rurais (poligonos), rios e corpos d'agua, linhas de transmissao de energia, e relevo/altitude. Ativar/desativar camadas ajuda a analisar o potencial da area."},{title:"Filtros rapidos",content:"Use os atalhos para buscar grandes fazendas (>1000ha) ou pequenas propriedades. Filtre por UF e municipio. O score gauge mostra a nota da oportunidade baseada nos criterios de proximidade."},{title:"Resiliencia",content:"O servidor do SICAR e instavel. O sistema faz ate 3 tentativas automaticas, alterna entre protocolos WFS 2.0 e 1.1, e mostra um botao de 'Tentar novamente' caso o servidor esteja fora do ar."}],flow:"Selecionar UF/Município → Carregar CAR → Analisar Camadas → Score de Oportunidade → Importar como Ativo"},{id:"relatorios",icon:D,title:"Relatorios",badge:"Analise",badgeColor:"bg-rose-500/10 text-rose-600 border-rose-200",summary:"Relatorios analiticos com abas por area: visao geral, empresas, deals e ativos. Graficos, tabelas e metricas detalhadas.",subsections:[{title:"Abas de relatorio",content:"O modulo tem 4 abas: Geral (KPIs consolidados, graficos de evolucao), Empresas (distribuicao por porte, estado, setor), Deals (funil de conversao, valor medio, taxa de fechamento), Ativos (distribuicao por tipo, valor medio, localizacao)."},{title:"Como usar",content:"Os relatorios sao gerados automaticamente com base nos dados do sistema. Use para acompanhar a performance da equipe, identificar gargalos no pipeline e reportar resultados para a diretoria."}]},{id:"status-servicos",icon:U,title:"Status de Servicos Externos",badge:"Sistema",badgeColor:"bg-gray-500/10 text-gray-600 border-gray-200",summary:"Indicadores visuais no sidebar mostram se os servicos externos (ANM e SICAR) estao disponiveis.",subsections:[{title:"Como funciona",content:"O sistema verifica a cada 60 segundos se os servidores da ANM (geo.anm.gov.br) e do SICAR (geoserver.car.gov.br) estao respondendo. O resultado aparece como uma bolinha verde (online) ou amarela com icone de alerta (indisponivel) ao lado dos itens 'Portal ANM' e 'Prospeccao Rural' no menu lateral."},{title:"Instabilidade do SICAR",content:"O servidor do SICAR e reconhecidamente instavel. E comum aparecer como 'offline'. Quando isso acontece, voce ainda pode tentar acessar o modulo Geo-Rural — o sistema faz ate 3 tentativas automaticas e alterna entre protocolos WFS."}]},{id:"connectors",icon:O,title:"Connectors",badge:"Sistema",badgeColor:"bg-gray-500/10 text-gray-600 border-gray-200",summary:"Gerenciamento de fontes de dados externas e jobs automatizados. Permite configurar, executar e monitorar conectores.",subsections:[{title:"O que sao Connectors",content:"Connectors sao integracoes com fontes de dados externas (APIs, planilhas, scrapers). Cada conector pode ser configurado com parametros JSON, executado manualmente ou agendado. O status mostra a ultima execucao e se foi bem-sucedida."},{title:"Quando usar",content:"Use quando precisar importar dados em massa de fontes externas, configurar scrapers automaticos ou integrar com outros sistemas. Este modulo e voltado para administradores."}]},{id:"users",icon:w,title:"Usuarios e Permissoes",badge:"Sistema",badgeColor:"bg-gray-500/10 text-gray-600 border-gray-200",summary:"Gerenciamento de usuarios com controle de acesso baseado em papeis (RBAC): Admin, Manager e Operador.",subsections:[{title:"Papeis e permissoes",content:"Admin: acesso total a todos os modulos, incluindo Connectors, Usuarios e Configuracoes. Manager: acesso a Dashboard, Prospeccao, Empresas e Ativos. Operador: acesso a Dashboard, Prospeccao, Empresas e Ativos. As permissoes podem ser customizadas por usuario."},{title:"Gerenciar usuarios",content:"Nesta pagina voce pode criar novos usuarios, alterar papeis, customizar permissoes individuais e configurar assinaturas de email."}]},{id:"configuracoes",icon:I,title:"Configuracoes",badge:"Sistema",badgeColor:"bg-gray-500/10 text-gray-600 border-gray-200",summary:"Configuracoes gerais do sistema: nome da empresa, logo, preferencias de idioma e tema.",subsections:[{title:"O que configurar",content:"Nesta pagina voce define o nome da sua empresa (usado nas propostas com {{minha_empresa.nome}}), a URL do logo, e outras preferencias gerais do sistema."}]},{id:"error-reports",icon:M,title:"Erros e Relatorios",badge:"Sistema",badgeColor:"bg-red-500/10 text-red-600 border-red-200",summary:"Sistema completo de reporte e rastreamento de bugs durante o periodo de testes, com captura automatica de erros.",subsections:[{title:"Reportar Bug",content:"Qualquer usuario pode reportar um bug clicando no botao 'Reportar Bug' na barra superior. O formulario permite descrever o problema, selecionar o modulo afetado e definir a prioridade (Baixa, Media, Alta, Critica). Informacoes como pagina atual, usuario e navegador sao incluidas automaticamente."},{title:"Captura Automatica",content:"O sistema captura automaticamente erros de requisicoes que falham (status 400+), erros de JavaScript nao tratados e rejeicoes de Promise. Esses erros aparecem no painel com o tipo 'Auto' e incluem detalhes tecnicos como URL, metodo HTTP, status code e stack trace."},{title:"Painel de Erros",content:"O painel de gerenciamento (acessivel pelo menu lateral em Sistema > Erros e Relatorios) mostra todos os erros com filtros por status, prioridade e tipo. Cada erro pode ser marcado como 'Em Analise', 'Resolvido' ou 'Fechado'. Cards de estatisticas no topo mostram totais, abertos, resolvidos e auto-capturados."},{title:"Notificacoes",content:"O sino de notificacoes na barra superior mostra a quantidade de erros pendentes em tempo real. Ao clicar, um menu dropdown lista os erros mais recentes com links diretos para o painel de gerenciamento."}]}],x=[{step:"1",label:"Prospectar",desc:"Buscar empresas por CNPJ, CNAE ou filtros avancados",module:"prospeccao"},{step:"2",label:"Importar Empresa",desc:"Salvar a empresa na base para acompanhamento",module:"empresas"},{step:"3",label:"Verificar Contato",desc:"Pesquisar e confirmar dados de contato na página da empresa",module:"empresas"},{step:"5",label:"Cadastrar Ativo",desc:"Registrar o imovel/mina/negocio com preco e detalhes",module:"ativos"}];funct